/* harness */
.hn{display:flex;flex-direction:column;width:100%;max-width:820px;height:600px;background:var(--panel);border:1px solid var(--line);overflow:hidden}
.hn-bar{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line)}
.hn-dot{width:8px;height:8px;background:var(--success)}
.hn-bar .t{font-size:14px;font-weight:600}
.hn-model{margin-left:auto;padding:3px 9px;border:1px solid var(--line);font-size:12px;font-weight:500;color:var(--text-dim)}
.hn-msgs{flex:1;overflow-y:auto;padding:20px 20px 10px;display:flex;flex-direction:column;gap:16px;scroll-behavior:smooth;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.hn-hello{margin:auto 0;text-align:center}
.hn-hello .h{font-size:24px;font-weight:600;letter-spacing:-.02em}
.hn-hello .d{margin-top:4px;font-size:14px;color:var(--text-dim)}
.hn-sugs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:20px;text-align:left}
.hn-sug{display:flex;flex-direction:column;gap:8px;padding:14px;border:1px solid var(--line);background:var(--panel);font-size:13.5px;font-weight:500;color:var(--text);text-align:left;transition:border-color .2s,background-color .2s}
.hn-sug:hover{border-color:var(--icon-line);background:var(--chip)}
.hn-sug .ms{color:var(--accent)}
.hn-u{align-self:flex-end;max-width:75%;padding:9px 13px;background:var(--chip);font-size:14px;animation:enter .35s var(--ease) both}
.hn-a{display:flex;flex-direction:column;gap:10px;max-width:92%;animation:enter .35s var(--ease) both}
.hn-a .tk2{max-width:none}
.hn-txt{font-size:14.5px;line-height:1.65;color:var(--text)}
.hn-card{border:1px solid var(--line);background:var(--panel);animation:enter .45s var(--ease) both}
.hn-card-h{display:flex;align-items:center;justify-content:space-between;padding:10px 14px;border-bottom:1px solid var(--line);font-size:13px;font-weight:600}
.hn-acts{display:flex;gap:8px;padding:10px 14px;border-top:1px solid var(--line)}
.hn-comp{display:flex;align-items:center;gap:8px;margin:0 16px 16px;padding:6px 6px 6px 14px;border:1px solid var(--icon-line);background:var(--panel)}
.hn-comp input{flex:1;min-width:0;height:34px;background:transparent;border:0;outline:0;font:inherit;font-size:14px;color:var(--text)}
@media (max-width:760px){ .hn-sugs{grid-template-columns:1fr} .pr-grid{grid-template-columns:1fr} .mc-cols{grid-template-columns:1fr} .mc-col+.mc-col{border-left:0;border-top:1px solid var(--line)} .tl-axis{margin-left:120px} .tl-row{grid-template-columns:120px 1fr} }

/* harness composer: squircle frame that matches the send button */
[data-style="soft"] .hn-comp{border-radius:16px}
@supports (corner-shape: squircle){ [data-style="soft"] .hn-comp{corner-shape:squircle;border-radius:22px} }.hn-mw{position:relative;margin-left:auto}
.hn-model{margin-left:0;cursor:pointer;transition:border-color .2s,color .2s}
.hn-model:hover,.hn-model[aria-expanded="true"]{border-color:var(--icon-line);color:var(--text)}
.hn-model .ms:last-child{transition:transform .3s cubic-bezier(.16,1,.3,1)}
.hn-model[aria-expanded="true"] .ms:last-child{transform:rotate(180deg)}
.hn-mm{position:absolute;top:calc(100% + 6px);right:0;z-index:20;width:250px;padding:4px;background:var(--panel);border:1px solid var(--line);box-shadow:0 18px 40px -18px rgba(17,19,24,.35);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top right;transition:opacity .18s ease,transform .3s cubic-bezier(.16,1,.3,1),visibility 0s linear .3s}
.hn-mm.open{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s cubic-bezier(.16,1,.3,1),visibility 0s}
.hn-mm button{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;padding:8px 10px;text-align:left}
.hn-mm button:hover{background:var(--bg)}
.hn-mm button > span:first-child{display:flex;flex-direction:column;gap:1px}
.hn-mm b{font-size:13px;font-weight:600;color:var(--text)}
.hn-mm i{font-style:normal;font-size:12px;color:var(--muted)}
.hn-mm .ms{opacity:0;color:var(--accent)}
.hn-mm button[aria-checked="true"] .ms{opacity:1}
[data-style="soft"] .hn-mm{border-radius:14px}
[data-style="soft"] .hn-mm button{border-radius:9px}

/* ---------- harness ---------- */
  {
    const msgs = $('#hn-msgs'), inp = $('#hn-in'), send = $('#hn-send');
    const SUGS = [['search','Audit the pricing page','audit'],['calendar','What is on my agenda today?','agenda'],['person_add','Invite Priya to the pricing file','invite']];
    let busy = false, ts = [];
    const later = (fn, ms) => ts.push(setTimeout(fn, ms));
    const scroll = () => { msgs.scrollTop = msgs.scrollHeight; };
    function hello(){ ts.forEach(clearTimeout); ts = []; busy = false; msgs.innerHTML = `<div class="hn-hello enter"><div class="h">What can I help with today?</div><div class="d">Pick a starter or ask anything.</div><div class="hn-sugs">${SUGS.map(s => `<button class="hn-sug" data-k="${s[2]}">${ic(s[0],'sm')}${s[1]}</button>`).join('')}</div></div>`; }
    function think(steps, cb){
      const a = document.createElement('div'); a.className = 'hn-a';
      a.innerHTML = `<div class="tk2"><button class="tk2-h" aria-expanded="true"><span class="ms sm tk2-ic">stars</span><span class="tk2-t shimmer fade-swap">Thinking</span><span class="ms sm tk2-chev">expand_more</span></button><div class="unfold open"><div class="uf"><div class="tk2-list"></div></div></div></div>`;
      msgs.appendChild(a); scroll();
      const list = a.querySelector('.tk2-list'), title = a.querySelector('.tk2-t'), head = a.querySelector('.tk2-h'), fold = a.querySelector('.unfold'), t0 = performance.now();
      head.addEventListener('click', () => { const o = head.getAttribute('aria-expanded') !== 'true'; head.setAttribute('aria-expanded', o); fold.classList.toggle('open', o); Sound.play(o ? 'open' : 'close'); });
      const tickLast = () => { const prev = list.lastElementChild; if (prev) prev.querySelector('.st').innerHTML = ic('check', 'sm icon-in'); };
      steps.forEach((s, i) => later(() => { tickLast(); const r = document.createElement('div'); r.className = 'tk2-row'; r.innerHTML = `<span class="st"><i class="spin"></i></span><span>${s[0]}</span>${s[1] ? `<span class="m">${s[1]}</span>` : ''}`; list.appendChild(r); ambient('c99', 'tick'); scroll(); }, 300 + i * 750));
      later(() => { tickLast(); title.classList.remove('shimmer'); swapText(title, `Thought for ${Math.max(1, Math.round((performance.now() - t0) / 1000))} seconds`); setTimeout(() => { head.setAttribute('aria-expanded', 'false'); fold.classList.remove('open'); }, 600); cb(a); }, 300 + steps.length * 750);
    }
    function say(a, text, cb){ const p = document.createElement('div'); p.className = 'hn-txt'; p.innerHTML = wordsHTML(text); a.appendChild(p); const r = revealWords(p, 32, i => { if (i % 3 === 0) ambient('c99', 'stream'); scroll(); }); later(() => cb && cb(), r.done + 150); }
    function card(a, html){ const c = document.createElement('div'); c.className = 'hn-card'; c.innerHTML = html; a.appendChild(c); scroll(); ambient('c99', 'pop'); return c; }
    const FLOWS = {
      signups:{ q:'How are sign-ups doing this month?', icon:'trending_up', steps:[['Read the analytics','30 days'],['Compared with last month','']],
        text:'Sign-ups are up 14% on last month, and most of the lift came from mobile. The biggest drop-off is between sign-up and activation.',
        card:a => card(a, `<div class="hn-card-h">Funnel, this month<span class="pill done"><i></i><span>+14%</span></span></div><div class="hn-bars">${[['Visited','12.4k',100],['Signed up','6.2k',50],['Activated','3.7k',30],['Paid','1.9k',15]].map(r => `<div class="hn-fbar"><span>${r[0]}</span><b><i style="--w:${r[2]}%"></i></b><span class="mono-xs">${r[1]}</span></div>`).join('')}</div>`), next:['board','tickets','audit'] },
      board:{ q:'What is the team working on?', icon:'folder', steps:[['Read the launch board','7 cards'],['Grouped them by owner','']],
        text:'Four things are in progress, and one is due today. The checkout QA needs attention first.',
        card:a => card(a, `<div class="hn-card-h">Launch board<span class="pill warn"><i></i><span>1 due today</span></span></div>${[['Agent status components',['design','dev'],'Maya Chen','Oct 8'],['Checkout flow QA',['qa'],'Jonas Weber','Today'],['Launch announcement',['copy','marketing'],'Ines Duarte','Oct 12']].map(r => `<div class="hn-task"><span class="kb-tags">${r[1].map(t => `<span class="kb-tag ${t}">${t === 'qa' ? 'QA' : t[0].toUpperCase() + t.slice(1)}</span>`).join('')}</span><span class="hn-task-t">${r[0]}</span><span class="kb-due ${r[3] === 'Today' ? 'late' : ''}">${r[3]}</span>${avatar(r[2])}</div>`).join('')}`), next:['reschedule','signups','invite'] },
      tickets:{ q:'Any urgent support tickets?', icon:'chat_bubble', steps:[['Read the inbox','5 open'],['Sorted by response time','']],
        text:'Two tickets are close to their response deadline. Joanna was charged twice, and I can refund the duplicate now.',
        card:a => { const c = card(a, `<div class="hn-card-h">Needs a reply<span class="pill fail"><i></i><span>2 urgent</span></span></div>${[['Joanna Kim','Charged twice for October','late','12m left'],['Sam Rivera','Can\u2019t invite my team','warn','38m left']].map(r => `<div class="hn-task">${avatar(r[0])}<span class="hn-task-t"><b>${r[0]}</b> ${r[1]}</span><span class="tkl-sla ${r[2]}">${r[3]}</span></div>`).join('')}<div class="hn-acts"><button class="btn primary" data-a="refund">Refund the duplicate</button><button class="btn" data-a="later">Later</button></div>`);
          c.addEventListener('click', e => { const b = e.target.closest('[data-a]'); if (!b) return; if (b.dataset.a === 'refund'){ b.disabled = true; b.innerHTML = '<i class="bt-spin"></i>Refunding'; Sound.play('tab'); later(() => { c.querySelector('.hn-acts').innerHTML = '<span class="mono-xs">Refunded $24.00 to Joanna Kim</span>'; Sound.play('done'); showToast('Refund sent'); }, 1100); } else { Sound.play('tick'); c.querySelector('.hn-acts').innerHTML = '<span class="mono-xs">Saved for later</span>'; } }); }, next:['board','agenda','signups'] },
      reschedule:{ q:'Move the pricing review to 3pm', icon:'calendar', steps:[['Checked everyone\u2019s calendars','3 people'],['Found a free slot','3:00 PM']],
        text:'Everyone is free at 3pm. Should I move the pricing review and let Oscar and Priya know?',
        card:a => { const c = card(a, `<div class="hn-card-h">Pricing page review<span class="pill warn"><i></i><span>Needs approval</span></span></div><div class="hn-move"><span class="old">1:30 to 2:30 PM</span>${ic('arrow_forward','sm')}<b>3:00 to 4:00 PM</b></div><div class="hn-acts"><button class="btn primary" data-a="move">Move it</button><button class="btn" data-a="keep">Keep 1:30</button></div>`);
          c.addEventListener('click', e => { const b = e.target.closest('[data-a]'); if (!b) return; const ok = b.dataset.a === 'move'; setPill(c.querySelector('.pill'), ok ? 'done' : 'todo', ok ? 'Moved' : 'Unchanged'); c.querySelector('.hn-acts').innerHTML = `<span class="mono-xs">${ok ? 'Oscar and Priya have the new time' : 'The review stays at 1:30'}</span>`; Sound.play(ok ? 'done' : 'close'); }); }, next:['invite','board','tickets'] },
      audit:{ q:'Audit the pricing page', steps:[['Opened the pricing page','3 sections'],['Checked contrast and spacing','24 checks'],['Followed every link','18 links']],
        text:'The page is in good shape. Two images need alt text and one link returns a 404, which I can fix now.',
        card:a => {
          const c = card(a, `<div class="hn-card-h">Audit results<span class="pill done"><i></i><span>21 passed</span></span></div>${[['check_circle','s-done','Colour contrast','Pass'],['nearby_error','s-run','Alt text on images','2 missing'],['error','s-fail','Broken links','1 found']].map(r => `<div class="lc-row ran" style="padding:9px 14px"><span class="st">${ic(r[0],'sm ' + r[1])}</span><span>${r[2]}</span><span class="r"><span class="mono-xs">${r[3]}</span></span></div>`).join('')}<div class="hn-acts"><button class="btn primary" data-a="fix">Fix the broken link</button><button class="btn" data-a="later">Later</button></div>`);
          c.addEventListener('click', e => {
            const b = e.target.closest('[data-a]'); if (!b) return;
            if (b.dataset.a === 'fix'){ b.disabled = true; b.innerHTML = '<i class="bt-spin"></i>Fixing'; Sound.play('tab'); later(() => { const row = c.querySelectorAll('.lc-row')[2]; row.querySelector('.st').innerHTML = ic('check_circle', 'sm s-done icon-in'); row.querySelector('.r').innerHTML = '<span class="mono-xs">Fixed</span>'; c.querySelector('.hn-acts').innerHTML = '<span class="mono-xs">Link updated to /pricing/compare</span>'; Sound.play('done'); showToast('Broken link fixed'); }, 1200); }
            else { Sound.play('tick'); c.querySelector('.hn-acts').innerHTML = '<span class="mono-xs">Saved for later</span>'; }
          });
        }, next:['tickets','signups','invite'] },
      agenda:{ q:'What is on my agenda today?', steps:[['Read your calendar','4 events'],['Checked the gaps between them','']],
        text:'You have three things today. The pricing review is up next.',
        card:a => card(a, `<div class="hn-card-h">Today<span class="mono-xs">${TODAY.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'short' })}</span></div><div style="display:flex;flex-direction:column;gap:8px;padding:12px">${[['m','Maya Chen','Kickoff with Northwind','9:00 to 9:45 AM',1],['b','Oscar Lind','Pricing page review','1:30 to 2:30 PM'],['l','Priya Nair','Design system workshop','4:00 to 5:30 PM']].map(e => `<div class="agd-c ev-${e[0]} ${e[4] ? 'past' : ''}">${avatar(e[1])}<span class="agd-tx"><span class="agd-tt">${e[2]}</span><span class="agd-tm" style="display:block">${e[3]}</span></span></div>`).join('')}</div>`), next:['reschedule','board','audit'] },
      invite:{ q:'Invite Priya to the pricing file', steps:[['Found Priya Nair','priya@northwind.co'],['Checked the file permissions','']],
        text:'Priya does not have access yet. Should I give her edit access to Pricing page v2?',
        card:a => {
          const c = card(a, `<div class="hn-card-h">Share Pricing page v2<span class="pill warn"><i></i><span>Needs approval</span></span></div><div class="iv-p" style="padding:12px 14px">${avatar('Priya Nair')}<div class="who"><div class="n">Priya Nair</div><div class="e">priya@northwind.co</div></div><span class="mono-xs">Can edit</span></div><div class="hn-acts"><button class="btn primary" data-a="allow">Send invite</button><button class="btn" data-a="deny">Cancel</button></div>`);
          c.addEventListener('click', e => { const b = e.target.closest('[data-a]'); if (!b) return; const ok = b.dataset.a === 'allow'; setPill(c.querySelector('.pill'), ok ? 'done' : 'todo', ok ? 'Invite sent' : 'Cancelled'); c.querySelector('.hn-acts').innerHTML = `<span class="mono-xs">${ok ? 'Priya can now edit the file' : 'Nothing was shared'}</span>`; Sound.play(ok ? 'done' : 'close'); if (ok) showToast('Invite sent to Priya Nair'); });
        }, next:['board','agenda','signups'] }
    };
    // after every answer, a few follow-ups show what else the agent can do, skipping what was already asked
    const asked = new Set();
    const ICONS = { audit:'search', agenda:'calendar', invite:'person_add' };
    function nextUp(a, keys){
      const pick = (keys || []).filter(k => !asked.has(k)).concat(Object.keys(FLOWS).filter(k => !asked.has(k))).filter((k, i, all) => all.indexOf(k) === i).slice(0, 3);
      const n = document.createElement('div'); n.className = 'hn-next';
      n.innerHTML = pick.length ? `<span class="mono-xs">Try next</span><div class="hn-chips">${pick.map(k => `<button class="hn-sug hn-chip" data-k="${k}">${ic(FLOWS[k].icon || ICONS[k] || 'stars','sm')}${FLOWS[k].q}</button>`).join('')}</div>` : `<span class="mono-xs">That is everything in this demo</span><div class="hn-chips"><button class="hn-chip" data-reset>${ic('refresh','sm')}Start a new chat</button></div>`;
      a.appendChild(n); scroll(); if (!reduce) $$('.hn-chip', n).forEach((c, i) => c.animate([{ opacity:0, transform:'translateY(6px)' }, { opacity:1, transform:'none' }], { duration:360, delay:120 + i * 70, easing:'cubic-bezier(.16,1,.3,1)', fill:'backwards' }));
    }
    function ask(text, key){
      if (busy) return; busy = true; const h = $('.hn-hello', msgs); if (h) h.remove(); $$('.hn-next', msgs).forEach(x => x.remove()); if (key) asked.add(key);
      const u = document.createElement('div'); u.className = 'hn-u'; u.textContent = text; msgs.appendChild(u); scroll(); Sound.play('send');
      const f = FLOWS[key] || { steps:[['Read the question',''],['Checked your workspace','3 projects']], text:'I can help with that. In a real product this is where the agent answers from your workspace and pulls in live components like the ones in this library.' };
      later(() => think(f.steps, a => say(a, f.text, () => { if (f.card) f.card(a); busy = false; later(() => nextUp(a, f.next), f.card ? 500 : 200); })), 400);
    }
    msgs.addEventListener('click', e => { const s = e.target.closest('.hn-sug'); if (s){ ask(FLOWS[s.dataset.k].q, s.dataset.k); return; } if (e.target.closest('[data-reset]')){ Sound.play('tab'); asked.clear(); hello(); } });
    inp.addEventListener('input', () => { send.disabled = !inp.value.trim(); });
    const go = () => { const v = inp.value.trim(); if (!v) return; inp.value = ''; send.disabled = true; ask(v, /move|resched|3pm/i.test(v) ? 'reschedule' : /agenda|calendar|today/i.test(v) ? 'agenda' : /invite|share/i.test(v) ? 'invite' : /sign.?up|growth|funnel|metric/i.test(v) ? 'signups' : /ticket|support|urgent|customer/i.test(v) ? 'tickets' : /team|board|working on|task/i.test(v) ? 'board' : /audit|pricing|check/i.test(v) ? 'audit' : null); };
    send.addEventListener('click', go); inp.addEventListener('keydown', e => { if (e.key === 'Enter') go(); });
    $('#hn-reset').addEventListener('click', () => { Sound.play('tab'); asked.clear(); hello(); });
    // model picker in the header
    { const mb = $('#hn-model'), mm = $('#hn-mm');
      const close = () => { mm.classList.remove('open'); mb.setAttribute('aria-expanded', 'false'); };
      mb.addEventListener('click', e => { e.stopPropagation(); const o = !mm.classList.contains('open'); mm.classList.toggle('open', o); mb.setAttribute('aria-expanded', o); Sound.play(o ? 'open' : 'close'); });
      mm.addEventListener('click', e => { const b = e.target.closest('[data-m]'); if (!b) return; $$('[data-m]', mm).forEach(x => x.setAttribute('aria-checked', x === b)); mb.querySelector('.hn-mn').textContent = b.dataset.m; close(); Sound.play('select'); showToast(`Switched to ${b.dataset.m}`); });
      document.addEventListener('click', e => { if (!e.target.closest('.hn-mw')) close(); });
      document.addEventListener('keydown', e => { if (e.key === 'Escape') close(); }); }

    hello();
  }
